closure_test.js
function outer() {
let count = 0;
return () => { count++; console.log(count); };
}
const counter = outer();
counter(); counter();
The inner function forms a closure. Even though outer() has finished executing, the
counter function maintains a reference to the count variable in its private lexical scope.

